async function api(path, options = {}) {
  const response = await fetch(path, {credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});
  let body; try { body = await response.json(); } catch { throw {code:'NETWORK_RESPONSE',message:'The workspace returned an unreadable response. Try again.'}; }
  if (!response.ok) throw {...(body.error || {code:'REQUEST_FAILED',message:'The request could not be completed.'}),httpStatus:response.status};
  return body;
}
