  const groups = [['Feedback & priority', ['INSUFFICIENT_EVIDENCE','HUMAN_PRIORITY_REQUIRED'], s.features[0].priority ? 'Human priority recorded' : 'Traceable evidence and a human decision'],['Beta exit', ['BETA_','MISSING_OWNER','MISSING_HYPOTHESIS','MISSING_METRIC','MISSING_DENOMINATOR','MISSING_TARGET','MISSING_OBSERVATIONWINDOW','ADVERSE_'], `Prototype thresholds · ${s.beta.sampleSize} setups / ${s.beta.observedDays} days`],['Security & privacy', ['MISSING_SECURITY','MISSING_PRIVACY'], 'Scoped synthetic review; no certification'],['Rollback & handoff', ['MISSING_ROLLBACK','ROLLBACK_FAILED','MISSING_GTM'], 'Test evidence and accountable handoff'],['Release signature', ['RELEASE_SIGNATURE','ROLLOUT_PAUSED','ROLLOUT_REVIEW_REQUIRED','NEW_SCOPE_REQUIRED'], 'Human decision bound to this exact version']];
