function decisionPresentation() {
  const s=data.state,r=s.release,g=gates();
  const phase=g.nextPhase;
  const phaseDecisions={
    feedback:{title:'Start with the source. Build the evidence trail.',label:'Review synthetic feedback',action:'import'},
    beta:{title:'Build a beta decision on measured evidence.',label:g.nextView==='feedback'?'Review the scoped opportunity':'Review beta evidence',action:`nav:${g.nextView||'release'}`},
    'beta-approval':{title:'Beta evidence is ready for human review.',label:'Review and approve beta',action:'form:approveBeta'},
    'release-evidence':{title:'Keep the release on hold. Close the evidence gaps.',label:'Review release gates',action:'nav:release'},
    'release-signature':{title:'Review the exact version. Sign the release.',label:'Review and sign release',action:'form:signRelease'},
    release:{title:'Current evidence is ready. Make the release call.',label:'Attempt simulated release',action:'release'},
    health:{title:'Observe the rollout. Own the outcome.',label:'Review health and outcome',action:'nav:health'},
    rollback:{title:'Pause the rollout. Resolve the owned rollback.',label:'Review owned rollback',action:'nav:health'},
    'post-review':{title:r.status==='rolled-back'?'Rollback resolved. Record what happened.':'Health recorded. Review the outcome.',label:'Record the post-review',action:'form:postReview'},
    'outcome-review':{title:'Review the outcome. Decide the next scope.',label:'Open weekly review',action:'nav:review'}
  };
  if(phaseDecisions[phase])return phaseDecisions[phase];
  if(r.status==='paused')return {title:'Pause the rollout. Resolve the owned rollback.',label:'Review owned rollback',action:'nav:health'};
  if(s.postReview&&['released','rolled-back'].includes(r.status))return {title:'Review the outcome. Decide the next scope.',label:'Open weekly review',action:'nav:review'};
  if(r.status==='rolled-back')return {title:'Rollback resolved. Record what happened.',label:'Record the post-review',action:'nav:health'};
  if(r.status==='released')return {title:'Observe the rollout. Own the outcome.',label:'Review health and outcome',action:'nav:health'};
  if(g.release.ready)return {title:'Current evidence is ready. Make the release call.',label:'Review release decision',action:'nav:release'};
  return s.sources.length?{title:'Keep the release on hold. Close the evidence gaps.',label:'Review release gates',action:'nav:release'}:{title:'Start with the source. Build the evidence trail.',label:'Review synthetic feedback',action:'import'};
}
