let data, fixtures, report, integrationReport, lastImportResult, busy = false, active = 'overview', feedbackFilter = 'all', preview, importRows, invalidationNotice = '', toastTimer;
const dialog = $('#editor-dialog');
async function api(path, options = {}) {
  const response = await fetch(path, {credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});
  let body; try { body = await response.json(); } catch { throw {code:'NETWORK_RESPONSE',message:'The workspace returned an unreadable response. Try again.'}; }
  if (!response.ok) throw {...(body.error || {code:'REQUEST_FAILED',message:'The request could not be completed.'}),httpStatus:response.status};
  return body;
}
function announce(message) { $('#announcer').textContent = message; }
function toast(message) { $('#toast').textContent = message; $('#toast').hidden = false; clearTimeout(toastTimer); toastTimer = setTimeout(() => { $('#toast').hidden = true; }, 6000); announce(message); }
const feature = () => data.state.features[0];
