  $('#app').innerHTML = `<div class="shell"><aside class="sidebar"><div class="brand-block"><span class="brand-symbol" aria-hidden="true">a.</span><div><div class="brand-name">Ayo Ahmed -<br class="desktop-break"> Independent concept</div><p class="brand-context">Independent concept for Semble</p></div></div><div class="nav-label">Workspace</div><nav class="nav" aria-label="Workspace">${navs.map(([id,label,ico]) => `<button data-nav="${id}" data-testid="nav-${id}" class="${active === id ? 'active' : ''}" ${active === id ? 'aria-current="page"' : ''}>${icon(ico)}${label}</button>`).join('')}</nav><div class="sidebar-footer"><span class="dot"></span>Visitor-isolated workspace<strong>One workflow. Every decision traced.</strong><p>Recorded synthetic observations.<br>No production connection.</p><button class="text-btn" data-action="reset" data-testid="reset-workspace">Reset synthetic workspace</button></div></aside><div class="main-wrap"><header class="topbar"><div class="topbar-title">Feedback → Release Proof <span>/ ${esc(navs.find(n=>n[0]===active)?.[1])}</span></div><div class="topbar-right"><span class="pill">${icon('lock')}Private synthetic session</span><span class="avatar" aria-hidden="true">AA</span></div></header><main id="main" class="content" tabindex="-1">${views[active]()}${footer()}</main></div></div>`;
  if (focus) $('#page-title')?.focus({preventScroll:true});
