function blockersBox(check, title) { return `<section class="panel section-gap"><div class="panel-head"><div><h2>${title}</h2><p>Computed by the server from current evidence</p></div>${status(check.ready?'Ready':'Blocked',check.ready?'good':'warn')}</div><div class="panel-body">${check.blockers.length?check.blockers.map(b=>`<div class="gate-row"><span class="gate-icon blocked">${icon('clock')}</span><div><strong>${esc(b.label)}</strong><p>${esc(b.owner)} · ${esc(b.nextAction)}</p></div><span class="pill">${esc(b.code)}</span></div>`).join(''):`<div class="notice mint"><div><strong>Current scoped evidence passes these prototype checks.</strong>A human still owns the decision. This result is not clinical or compliance certification.</div></div>`}</div></section>`; }
