    gtm:{title:'Save GTM and support handoff',description:'This is a scoped handoff record. Saving any revision invalidates the existing release signature.',type:'recordGtm',save:'Save handoff revision',fields:[owner(r.gtm?.owner || 'Synthetic GTM owner'),field('audience','Synthetic audience',r.gtm?.audience || 'Internal synthetic beta teams'),notes('message','Change message',r.gtm?.message || 'Reminder setup clarity experiment: fewer steps and clearer status. Synthetic operational scope; no clinical capability change.'),notes('supportPlan','Support plan and escalation route',r.gtm?.supportPlan || 'Synthetic Support owner monitors setup failures, links each signal to its exact source and escalates repeated failures to the Synthetic Engineering owner.')]},
