    healthy:{title:'Record a synthetic healthy check',description:'Requires a simulated rollout. A later healthy check cannot clear a pending failed-health rollback.',type:'recordHealth',save:'Record healthy observation',fields:[owner(r.health?.owner || 'Synthetic Engineering owner'),notes('note','Health observation evidence','Synthetic reminder setup checks pass in the scoped window; status events match expected setup outcomes.')],payload:v=>({...v,healthy:true})},
    failed:{title:'Simulate a failed health check',description:'The server pauses the simulated rollout, invalidates its signature and creates a rollback owned by the named person.',type:'recordHealth',save:'Record failure and owned pause',fields:[owner(r.health?.owner || 'Synthetic Engineering owner'),notes('note','Failure evidence and immediate action','Synthetic health probe detected repeated reminder setup failure. Pause the simulated rollout and restore the prior setup flow.')],payload:v=>({...v,healthy:false})},
    resolveRollback:{title:'Resolve the owned rollback',description:'Requires a failed health check and paused rollout. Resolution records a synthetic rollback and opens the post-review.',type:'resolveRollback',save:'Record rollback resolution',fields:[owner(r.rollbackAction?.owner || 'Synthetic Engineering owner'),notes('evidence','Resolution and verification evidence',r.rollbackAction?.evidence || 'Synthetic rollback completed: previous setup flow restored; event queue checked for duplicate processing; repeated setup attempts recover. Follow-up owner reviews the failure before a new scoped release.')]},
    postReview:{title:'Record the post-release review',description:'The server requires rollout health and resolution of any pending rollback. Leave the baseline blank when it is unknown; no improvement claim is made.',type:'postReview',save:'Save observed outcome',fields:[owner(s.postReview?.owner || f.owner),notes('observedOutcome','Observed synthetic outcome',s.postReview?.observedOutcome || 'Synthetic rollout was paused after failed health evidence and the tested rollback restored the prior setup flow.'),field('baseline','Comparable baseline (blank = unknown)',s.postReview?.baseline??'','number',{optional:true,min:0,max:10000,step:.01}),field('measured','Measured successful setups',s.postReview?.measured??38,'number',{min:0,max:10000,step:.01}),field('denominator','All attempted setups (denominator)',s.postReview?.denominator??40,'number',{min:1,max:10000,step:1}),field('window','Observation window',s.postReview?.window || 'Seven full synthetic days'),notes('notes','Limitations and next action',s.postReview?.notes || 'Baseline missing; no efficiency or causal gain claimed. Investigate repeated failures and collect a comparable pre-change cohort.')],payload:v=>({...v,baseline:v.baseline===''?null:Number(v.baseline),measured:Number(v.measured),denominator:Number(v.denominator)})},
    weeklyReview:{title:'Record this week’s operating decision',description:'Connect the decision to evidence and the next accountable action. Leave unknown baseline blank; invented observations are not production outcomes.',type:'weeklyReview',save:'Save weekly review',fields:[owner(s.weeklyReview?.owner || f.owner),notes('decision','Human decision and evidence',s.weeklyReview?.decision || 'Keep the scoped release on hold until beta and owner reviews are complete; treat ambiguous feedback as a coverage gap.'),notes('nextAction','Next action and accountable owner',s.weeklyReview?.nextAction || gates().nextDecision),field('baseline','Comparable baseline (blank = unknown)',s.weeklyReview?.baseline??'','number',{optional:true,min:0,max:10000,step:.01}),field('observed','Synthetic observations reviewed',s.weeklyReview?.observed??s.sources.length,'number',{min:0,max:10000,step:.01})],payload:v=>({...v,baseline:v.baseline===''?null:Number(v.baseline),observed:Number(v.observed)})},
    notification:{title:'Draft a synthetic notification',description:'No external message is sent. The server deduplicates the fixed event and audience, suppresses synthetic opt-out and limits simulated dispatch.',type:'enqueueNotification',save:'Queue synthetic notification',fields:[field('event','Workflow event','weekly-review','select',{options:['beta-approved','release-ready','rollback','weekly-review']}),field('audience','Synthetic audience','internal-synthetic','select',{options:['internal-synthetic','synthetic-opt-out']}),notes('message','Synthetic message','Synthetic internal update: review current reminder setup evidence and owner actions in this workspace.')]},
    reset:{title:'Reset the synthetic workspace',description:'This clears the current operational fixture. Revision-ordered audit history remains bounded in the current visitor session.',type:'reset',save:'Reset synthetic workspace',fields:[]},
    release:{title:'Attempt the simulated release',description:'The server checks every current gate. A blocked attempt writes nothing; a successful attempt records a synthetic rollout only.',type:'simulateRelease',save:'Attempt simulated release',fields:[]}
