function setPreset(key){const rows=fixtures.FIXTURE_SETS?.[key]||fixtures.SAMPLE_ROWS;$('#import-json').value=JSON.stringify(rows,null,2);preview=null;importRows=null;$('[data-testid="import-commit"]').disabled=true;$('#import-preview-results').innerHTML='';$('#form-error').hidden=true;}
function renderPreview(){const p=preview;$('#import-preview-results').innerHTML=`<section class="preview"><h3>${p.canCommit?'Verified preview — review before commit':'Batch refused — no rows will be saved'}</h3><div class="stats"><div class="stat"><div class="stat-top">Unique accepted</div><div class="stat-value">${p.accepted.length}</div><div class="stat-note">${p.evidence.length} supporting</div></div><div class="stat"><div class="stat-top">Duplicate / ambiguous</div><div class="stat-value">${p.duplicates.length} / ${p.ambiguous.length}</div><div class="stat-note">Excluded from added support</div></div><div class="stat"><div class="stat-top">Rejected rows</div><div class="stat-value">${p.rejected.length}</div><div class="stat-note">Atomic batch · r${p.revision}</div></div></div>${p.rejected.map(r=>`<div class="preview-row"><strong>${status(r.code,'bad')} · ${esc(r.sourceId)}</strong>${esc(r.reason)}</div>`).join('')}${p.duplicates.map(r=>`<div class="preview-row"><strong>${status('Duplicate counts once','warn')} · ${esc(r.sourceId)}</strong>${esc(r.reason)}</div>`).join('')}${p.ambiguous.map(r=>`<div class="preview-row"><strong>${status('Ambiguous','warn')} · ${esc(r.sourceId)}</strong>${esc(r.reason)}</div>`).join('')}${p.evidence.map(r=>`<div class="preview-row"><strong>${esc(r.sourceId)} · ${esc(r.theme)}</strong>“${esc(r.quote)}” · exact span [${r.start}, ${r.end})</div>`).join('')}<p class="small-copy section-gap">${p.canCommit?'Only this verified batch can be committed at this workspace revision.':'Fix every rejected row and preview again. Valid rows in this refused batch are not saved.'}</p>
  </section>`;$('[data-testid="import-commit"]').disabled=!p.canCommit;announce(p.canCommit?'Preview complete; verified batch can be reviewed and committed.':'Batch refused. No rows saved.');}
async function exportSnapshot(){try{const snapshot=await api('/api/export');const blob=new Blob([JSON.stringify(snapshot,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`ayo-feedback-release-proof-r${data.state.revision}-synthetic.json`;a.click();URL.revokeObjectURL(url);toast('Safe synthetic snapshot exported. Session identifiers and command receipts excluded.');}catch(error){toast(error.message);}}
async function evaluate(){const button=$('[data-testid="run-evaluation"]');if(button)button.disabled=true;toast('Running isolated server evaluation…');try{report=await api('/api/eval',{method:'POST',body:'{}'});if(report.report)report=report.report;if(integrationReport)report.integration=integrationReport;render();toast(`Evaluation complete: ${report.baseline.passed}/${report.baseline.scenarioCount} baseline scenarios passed; ${report.injectedFaults.detected} injected failures detected.`);}catch(error){toast(error.message);if(button)button.disabled=false;}}
document.addEventListener('click',async e=>{
  const nav=e.target.closest('[data-nav]');if(nav){go(nav.dataset.nav);return;}
  const filter=e.target.closest('[data-filter]');if(filter){feedbackFilter=filter.dataset.filter;render();$(`[data-filter="${feedbackFilter}"]`)?.focus();return;}
  const preset=e.target.closest('[data-preset]');if(preset){setPreset(preset.dataset.preset);return;}
  const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
  if(action.startsWith('nav:'))return go(action.slice(4));if(action.startsWith('form:'))return openForm(action.slice(5));if(action.startsWith('import:'))return openImport(action.slice(7));
  if(action==='import')return openImport();if(action==='close-dialog')return closeDialog();if(action==='release')return openForm('release');if(action==='reset')return openForm('reset');if(action==='export')return exportSnapshot();if(action==='evaluate')return evaluate();if(action==='dispatch')return command('dispatchOutbox',{},'Simulated dispatch');if(action==='reload'){try{data=await api('/api/state');dialog.close();render();toast('Loaded current server revision. Reopen the form before saving.');}catch(error){showError(error);}return;}
  if(action==='import-commit'&&preview?.canCommit&&importRows)return command('importRows',{rows:importRows,previewId:preview.previewId},'Verified synthetic import');
});
dialog.addEventListener('cancel',e=>{if(busy)e.preventDefault();});
window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(views[view]&&active!==view){active=view;render(true);}});
async function boot(){try{try{data=await api('/api/state');}catch(error){if([401,410].includes(error.httpStatus))data=await api('/api/session',{method:'POST',body:'{}'});else throw error;}active=views[location.hash.slice(1)]?location.hash.slice(1):'overview';render();fetch('/eval-report.json').then(r=>r.ok?r.json():null).then(r=>{if(r){integrationReport=r.integration||integrationReport;if(!report)report={...r,_recorded:true};else if(integrationReport)report.integration=integrationReport;if(active==='evaluation')render();}}).catch(()=>{});fetch('/integration-report.json').then(r=>r.ok?r.json():null).then(r=>{if(r){integrationReport=r;if(report)report.integration=r;if(active==='evaluation')render();}}).catch(()=>{});}catch(error){$('#app').innerHTML=`<div class="boot"><span class="brand-symbol" aria-hidden="true">a.</span><h1>Ayo Ahmed - Independent concept</h1><p>Independent concept for Semble</p><div class="notice danger section-gap"><div><strong>Workspace could not open</strong>${esc(error.message)}</div></div><button class="btn" id="retry-session">Retry synthetic workspace</button><p class="disclaimer section-gap">Unofficial. Synthetic operational data only. Not connected to Semble. Not a clinical system or compliance certification.</p></div>`;$('#retry-session').addEventListener('click',boot);}}
